        title: "How Many Emergency Drills Are Required Per Year?",
        content: "Joint Commission standard EM.03.01.01 requires hospitals to conduct at least two emergency exercises per year. At least one must be a community-based exercise, one that involves external agencies such as local EMS, fire department, public health, or neighboring hospitals. Drills must test the EOP and expose gaps. Both exercises must be documented, including the date, type of exercise, participants, a critique or evaluation, and any corrective actions identified. 'Tabletop exercises' (discussion-based) can count, but the standard requires at least some functional elements to be tested.",
        keyPoint: "Minimum: 2 exercises per year. At least one must involve community/external agencies. Both must be documented with critique and corrective actions.",
        category: "number",
