        title: "After-Action Reviews (EM.04.01.01)",
        content: "After every emergency drill and every actual emergency, the facility must conduct an after-action review (AAR). The AAR is a structured debrief that identifies what went well, what didn't, and what specific improvements need to be made to the EOP or response procedures. The JC standard EM.04.01.01 requires the AAR findings to be documented and tracked. Identified corrective actions must be assigned to responsible parties and followed up to verify they were completed. An AAR that produces findings no one ever acts on is a compliance failure, the improvement loop must close.",
